jQuery(function(a){if("function"==typeof window._klarnaCheckout&&"undefined"!=typeof kcoUpsellParams){let l={tableSelector:".woocommerce-order-details",pendingSelector:".kco-upsell-pending",maxAttempts:5,retryDelay:1500,init(){window._klarnaCheckout(function(e){e.on({upsell_product_added(){l.refresh(!1,1)},upsell_add_failed(){l.refresh(!0,1)}})})},refresh(r,t){a.ajax({url:kcoUpsellParams.url,type:"POST",data:{order_id:kcoUpsellParams.order_id,key:kcoUpsellParams.order_key,failed:r?1:0},success(e){e.success&&(e=a("<div>").append(a.parseHTML(e.data.html)).find(l.tableSelector)).length&&(a(l.tableSelector).replaceWith(e),e.find(l.pendingSelector).length)&&t<l.maxAttempts&&setTimeout(()=>l.refresh(r,t+1),l.retryDelay)}})}};l.init()}});
